/* One delegated effect survives route changes without delaying navigation. */
(()=>{const motion=matchMedia('(prefers-reduced-motion: reduce)'),colors=['#ffc94a','#a6e05a','#ff7a59','#fff8e1'];let layer;const presses=new WeakMap();const selector='button,[role="button"],.btn,.kid-primary,.header-enter,nav a,.fs-nav a,.fs-primary-link,.fs-return-link,.fs-cta,.discovery-player';document.addEventListener('click',event=>{const target=event.target.closest?.(selector);if(!target||target.disabled||target.getAttribute('aria-disabled')==='true'||motion.matches)return;const r=target.getBoundingClientRect();if(!r.width||!r.height)return;presses.get(target)?.cancel();presses.set(target,target.animate([{scale:'1'},{scale:'.94',offset:.25},{scale:'1.035',offset:.65},{scale:'1'}],{duration:320,easing:'ease-out'}));if(!layer){layer=document.createElement('div');layer.className='button-confetti-layer';layer.setAttribute('aria-hidden','true');document.body.append(layer)}if(layer.childElementCount>=100)return;const x=r.left+r.width/2,y=r.top+r.height/2;for(let i=0;i<50;i++){const dot=document.createElement('i'),angle=Math.random()*Math.PI*2,distance=140+Math.random()*280;dot.style.cssText=`left:${x}px;top:${y}px;background:${colors[i%colors.length]};width:${5+Math.random()*5}px;height:${8+Math.random()*6}px`;layer.append(dot);dot.animate([{transform:'translate(-50%,-50%) rotate(0)',opacity:1},{transform:`translate(${Math.cos(angle)*distance}px,${Math.sin(angle)*distance+200}px) rotate(${Math.random()*900}deg)`,opacity:0}],{duration:1400,easing:'cubic-bezier(.1,.8,.3,1)'}).onfinish=()=>dot.remove()}},true)})();
